# Classify each CMMagicPose surface change by whether SpringBoard propagated it.
import json,sys,datetime,collections
def load(path):
  rows=[]
  for l in open(path):
    try:e=json.loads(l)
    except:continue
    if 'timestamp' not in e or not e.get('processImagePath','').endswith('SpringBoard'):continue
    rows.append((e['timestamp'][:26],e.get('category',''),e.get('eventMessage','')))
  return rows
tally=collections.Counter();out=[]
for run in sys.argv[1:]:
  rows=load(run+'/guest-pose.ndjson')
  for i,(ts,c,m) in enumerate(rows):
    if c=='DevicePose' and 'surface orientation changed' in m:
      t=datetime.datetime.strptime(ts,'%Y-%m-%d %H:%M:%S.%f')
      win=[]
      for j in range(max(0,i-12),min(len(rows),i+40)):
        t2=datetime.datetime.strptime(rows[j][0],'%Y-%m-%d %H:%M:%S.%f')
        if abs((t2-t).total_seconds())<=0.005:win.append(rows[j])
      hinge=any('Hinge state changed' in x[2] for x in win)
      flip=any('Transition style .fade -> .continuousSnapshot' in x[2] for x in win)
      prop=any(x[1]=='DeviceOrientationUpdateDeferral' and 'Device pose changed' in x[2] for x in win)
      k=('hinge' if hinge else 'orient','flip' if flip else 'noflip','propagated' if prop else 'DROPPED')
      tally[k]+=1;out.append((run,ts[11:23],m.split('changed: ')[1],*k))
for o in out:print(*o)
print();[print(v,k) for k,v in sorted(tally.items())]

