import diag as d,subprocess,time,json,select
class Peer:
 def __init__(self,name):self.name=name;self.log=[]
 def read(self,timeout=12):
  assert select.select([self.proc.stdout],[],[],timeout)[0],"peer output timeout"
  line=self.proc.stdout.readline();assert line,"peer ended unexpectedly"
  item=json.loads(line);item['host_observed_at']=d.now();self.log.append(item);self.save();return item
 def save(self):(d.P/(self.name+'-peer.json')).write_text(json.dumps(self.log,indent=2))
 def __enter__(self):
  self.err=(d.P/(self.name+'-peer.stderr')).open('w');self.proc=subprocess.Popen([str(d.P/'vendor-peer')],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=self.err,text=True,bufsize=1,env=d.E);self.log.append({'event':'spawn','host_at':d.now(),'pid':self.proc.pid});self.ready=self.read();assert self.ready['event']=='ready';return self
 def send(self,command):
  self.proc.stdin.write(command+'\n');self.proc.stdin.flush();r=self.read();assert r['event']=='sent' and r['command']==command;return r
 def __exit__(self,*args):
  if self.proc.poll() is None:
   self.proc.stdin.write('quit\n');self.proc.stdin.flush();self.closed=self.read();assert self.closed['event']=='closed'
  self.proc.wait(timeout=10);self.err.close();self.save()

